INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1103096-ee360', 'stk-user7238', 'EE 360', 'info', '{"desc": "اشوف ان الكتاب حلوو وفيه كلام مفيد جدا والامثله جيده\nلكن المشكله انه طويل يعني لاتعتمد عليه اذا قرب الميجر\nوشي ثاني ان في مواضيع ماهي مطلوبه مننا\nهذا من خلال الي شفته من شابتر 1 الى الان", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-360-electric-energy-engineering/120702/13", "user": "user7238", "ts": 1349375303000, "tid": 120702, "pn": 13}}', 1349375303000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1167539-ee360', 'stk-user1091', 'EE 360', 'info', '{"desc": "السلام عليكم\n\nالكورس مثل ما قالوا أساس المتخصص في البور\n\nويتكلم عن ثري فيس سيستم وحساب الأحمال وعن المحولات والمولدات والمواطير وخطوط النقل وكيف تحسب الفولت والكرنت وتسوي مودل لهذه الأجهزة\n\nوما تقدر تتخصص في البور (الطاقة) إلا لما تاخذه\n\nيعني باختصار بوابة البور\n\nالكتاب جيد لكن صراحة من وجهة نظري ما يكفي في الشرح\n\nأنصح بالاستعانة بعد الله بملخصات قديمة فيها أمثلة مثل ملخص للهموز ومنطاوي وشكري", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-360-electric-energy-engineering/120702/15", "user": "user1091", "ts": 1358848324000, "tid": 120702, "pn": 15}}', 1358848324000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1424783-ee360', 'stk-user9496', 'EE 360', 'info', '{"desc": "الكورس سهل وممتع ، يتكلم عن 4 اشياء فقط\n\n1- Three phase balanced systems\n2- magnetic circuits\n3- DC machines\n4- AC machines\n\nومحاضرتين صغيرة بالنهاية عن ال transmission lines\n\nتقييم صعوبة الكورس 4/10", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-360-electric-energy-engineering/120702/17", "user": "user9496", "ts": 1440093437000, "tid": 120702, "pn": 17}}', 1440093437000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467339-ee360', 'stk-abo-da7m', 'EE 360', 'info', '{"desc": "أخذته فصل 161 مع الدكتور الرائع بلحاج شكري\n\nجودة المقرر بشكل عام\nممتاز ومفيد جدا ومقدمة أساسية لمواضيع الطاقة والقدرة والمولدات.\n\nالمواضيع التي يغطيها المقرر\nيبدأ بالثري فيز سيركتس بعدين الدوائر المغناطيسية (شبيهة بالدوائر الكهربائية) يدرس أنواع مختلفة من المولدات والمحركات وينتهي بخطوط النقل.\n\nهذا ال Syllabus:\nOutline-EE360-161-Cor.pdf\n\nالكتاب المستخدم للمقرر\nPrinciples of Electric Machines and Power Electronics, By: P.C. Sen, 2013, 3rd edition\nشرحه وأمثلته مقتضبة، ينفع كملخص ومراجعة للشخص اللي درس المادة قبل. ما أعتقد ينفع كتأسيس للي جديد بالمجال لإنه ما يشرح بتفصيل وحبة حبة.\n\nفيه كتاب بديل اسمه\nElectric Machinery Fundamentals, Stephen J. Chapman. Fifth Edition.\nرائع جدا وشامل ويشرح بتفصيل ووضوح.\n\nتقدر تحمله من هنا - لو الرابط لسا شغال - :\nhttps://www.google.com.sa/url?sa=t&rct=j&q=&esrc=s&source=web&cd=2&cad=rja&uact=8&ved=0ahUKEwiOlPfM5OrRAhWJQBoKHeyOCyUQFggfMAE&url=http://www.bank.engzenon.com/download/53a98ee3-5b14-4e63-bb84-6e4ec0e8c6f8/Electric_Machinery_Fundamentals_-_5th_Ed_Chapman.pdf&usg=AFQjCNFtqbFH_x9TgNip0UHR27MfA_SVyQ&sig2=gA-ID2Bm_hUocQHYsLLcow\n\nالأسئلة والأمثلة المستخدمة في المقرر\nأسئلة الكتاب شاملة لحد بعيد وتغطي الاختبارات، بس أمثلته قليلة.\n\nمدى فائدته في الناحية التطبيقية\nمفيد جدا وأساسي.\n\nإضافات\n* المقرر يعتبر متوسط السهولة إلى سهل، ما فيه مفايهم معقدة ولا يحتاج تمرين كثير.\n\n* ما اعتقد الاعتماد على الكتاب فكرة جيدة إلا إذا بتستخدم كتاب غير المقرر للمادة - مثل Electric Machinery Fundamentals اللي ذكرته فوق - .\n\n* إذا نزلته مع الدكتور شكري، أحرص تكتب معه أول بأول وبيعفيك عن كثير تعب ولا راح تحتاج الكتاب إلا بحالات قليلة للاستزادة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-360-electric-energy-engineering/120702/18", "user": "abo-da7m", "ts": 1485810884000, "tid": 120702, "pn": 18}}', 1485810884000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1485154-ee360', 'stk-mr.a1', 'EE 360', 'info', '{"desc": "Term 171 with Belhaj Chokri\n\nجودة المقرر بشكل عام\nيعطيك مقدمة جيدة في هندسة الطاقة ، بالإضافة للتعرف على عدة أنواع من المكائن الكهروميكانيكية الأساسية.\n\nالمواضيع التي يغطيها المقرر\nThree Phase Circuit (Review from EE 213)\nMagnetic Circuits\nTransformers\nDC Machines\nSynchronous Machines\nInduction Motor\nTransmission Lines\n\nالكتاب المستخدم للمقرر\nكمرجع أشوفه كويس ، وممكن تستفيد منه. الدكتور كان يرفع لنا أجزاء من كتاب ثاني ، أشوفه أفضل من الكتاب اللي يعطونه للطلاب.\n\nالأسئلة والأمثلة المستخدمة في المقرر\nنوعا ما واقعية وقريبة من الأشياء اللي تشوفها في الواقع. الأمثلة الموجودة في الكتاب والواجبات والأولد اقزام تقريبا نفس المستوى.\n\nمدى فائدته في الناحية التطبيقية\nمهم جدا سواء بتتابع في مجال الطاقة أو لا ، مقرر أساسي وهو أحد المقررات الستة في المستوى الثالث ، اللي هي أساس التخصص.\n\nإضافات:\n١. المقرر من أسهل مقررات المستوى الثالث في التخصص ، ودائما آفرجه عالي. لا تضيع درجات كثير فيه. طبعا هذا ما يعني إنك ما تذاكر له وتعطيه حقه.\n٢. فيه كلام إنهم راح يضيفون Induction Generators على المادة ، لكن ما عندي علم أكيد عن هالمعلومة.\n٣. لاب المادة من أخف وأسهل اللابات ، راح يتعبك اشوي أول تجربتين إلى ٣ تجارب ، بعدين بيبدأ الشغل يتكرر ويصير سريع جدا وسهل. إحرص على الاستفادة من اللاب قدر الامكان -ولو إن المكائن مهدود حيلها من كثر الاستخدام 😆- ، وإن شاء الله بتفهم المادة أكثر.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-360-electric-energy-engineering/120702/19", "user": "Mr.A1", "ts": 1514454168000, "tid": 120702, "pn": 19}}', 1514454168000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p601953-ee360', 'stk-user3985', 'EE 360', 'info', '{"desc": "حرام عليك تضيع الــ A+ عنده والله العظيم\n\nالدكتور مسهل الماده جدا جدا جدا جدا جدا جدا جدا جدا\n\nباختصار داكر النوت والاسئله اللي فيه\nحل الاسئله اللي يعطيكم وياها نهاية كل شابتر\nحل اسئله الهومورك وبس\n\nفي العاده كل اسئلته (problem solving)\n\nادعيلي بعد ماتجيب A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee360/86116/2", "user": "user3985", "ts": 1273314328000, "tid": 86116, "pn": 2}}', 1273314328000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1113912-ee360', 'stk-faisal91', 'EE 360', 'info', '{"desc": "ماتيريال الميجر transformers + DC machine\nبالنسبة للكتاب على كلام دكتورنا يقول الي شرحناه بالكلاس تقدرون تذاكرونه من الكتاب!! قاله طالب يحدد ارقام السكاشن حقت الكتاب الي نذاكر منها قال ما اقدر لان فيه سكاشن بالكتاب ناخذ منها جزئية بسيطه وفيه سكاشن نحذف منها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-ee360/134185/4", "user": "FAISAL91", "ts": 1352338063000, "tid": 134185, "pn": 4}}', 1352338063000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1226937-ee360', 'stk-user7645', 'EE 360', 'info', '{"desc": "السلام عليكم\n\nي اخوان بتحصلون بهذا الملف \" مياجر \\ أسئلة هووم وورك \\ بروبلم سيشن \\ مسائل وكويزات ، على كل المتريال :\n\nhttps://www.dropbox.com/sh/ypogd3mahnnpq7o/ETHjpOWEMh\n\nوبتحصلون بهذا الملف اسئلة خارجية محلوله على كل شابتر بالخطوات إذا فهمتوها فالفاينل بيكون برداً وسلاماً إن شاء الله 😆\n\nhttps://www.dropbox.com/sh/f3922b2q2i2vikb/VL_ZTr1auE\n\nالله يوفقكم يارب .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/final-ee360/145002/4", "user": "user7645", "ts": 1369343560000, "tid": 145002, "pn": 4}}', 1369343560000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1117782-ee360', 'stk-mr.all', 'EE 360', 'info', '{"desc": "السلام عليكم\nمساء الخير اخواني\n\nاختبار ee360 يوم السبت اسال الله ان يوفقنا أجمعين\nاخذت نظرة سريعة على المواضيع المطلوبة وهي\nTransformers CH2\nDC Machinery Fundamentals CH7\nDC Motors & Generators CH8\nموضوع Transformers أسهل شي بإمكانك فهمه من الكتاب، واضح بشكل جيد وسهل\n\nلكن الموضوعين الاخريين أشعر بأنها صعبة بالحيل، حاولت أفهمها من الكتاب لكن فيه\nقوانين كثيرة خاصة بالمفاهيم “Conceptual Equations” مالها علاقة بطريقة الحل\n\nأرجو أن نضم جهودنا لتعم الفائدة، وننشط هالقسم الميت جدا شويتين\nكل من عنده مداخلة أو معلومة أو ملفات قيمة لا يبخل بها، أرجو المشاركة ، أرجو المشاركة\n\nتحياتي وتمنياتي لكم بالسعادة والتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-360/134759/1", "user": "Mr.All", "ts": 1352987338000, "tid": 134759, "pn": 1}}', 1352987338000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p403405-ee360', 'stk-user5474', 'EE 360', 'info', '{"desc": "نعم نفس الماده بالظبط\n\nولكن طلاب الكهرب يدرسون شابتر واحد زياده فقط وانا متاكد من الكلام\n\nاتوقع المفروض تعادل المادتين\n\nجزاك الله خير على المعلومة\n\nأنا حاليا قاعد أجهز خطبة عصماء ألقيها على رئيس القسم علشان يلغي عني المادة بس شكلي بأخلي إلقائها للفصل الجاي : )\n\nيامن يعيش 9 شهور الحين أنا مشغول بالمياجر و التسجيل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-360-ee-306/73212/3", "user": "user5474", "ts": 1242501194000, "tid": 73212, "pn": 3}}', 1242501194000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1320887-ee360', 'stk-dok116', 'EE 360', 'info', '{"desc": "stat 319\nأنا نزلتها مع محمد صالح و ماكنت أذاكر إلا من الأسئلة اللي في النوت تبعه (مافكيت الكتاب إلا للجداول) وطلعت بقريد كويس\n\nEE 306\nأخذتها مع شكري بلحاج, كنت أكتب معاه وغالباً أسئلة المياجر تكون مشابهة للأمثلة تبعه, تقدر تحمل من التراكر ملف لـEE360 وشوف الأولد إكزامز والأولد كويزز لشكري, ميزة المادة ان الأسئلة تكون مكررة ومتشابهه\n\nمواد السيستم على حسب دكتورك, لكن بشكل عام للمادتين ما احتجت الكتاب , السلايدات كانت كافية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stat-ise/155432/15", "user": "dok116", "ts": 1390176426000, "tid": 155432, "pn": 15}}', 1390176426000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p404172-ee360', 'stk-_l_p_c_no', 'EE 360', 'info', '{"desc": "قصدك ee360 نزلها مع ابيدو وانت مغمض … الدكتور شريح … يحضر بداية المحاضره …تقريبا كويز كل اسبوعين … هوم وورك كل اسبوعين … مياجره سهله … ودورله مياجر قديمه يجيب منها … قريد يعطيك اللي متتوقعه … فمصلا تتوقع b فانت بتأخذ b+أو a…طبعا في هذه الماده ما يبغاله تشغيل المخ بكثر ما يبغالها الحس الهندسي …\n\nاللاب ما تفرق خذه مع اي احد … وما اعرف احد منهم…\n\nوالحموز … لا تفكر تنزل عنده", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/083-091/72948/92", "user": "_l_p_c_no", "ts": 1242676711000, "tid": 72948, "pn": 92}}', 1242676711000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1430644-ee360', 'stk-ahmed_sh', 'EE 360', 'info', '{"desc": "كورس EE 360 هو كورس اساسيات الآلات الكهربائية ويعتبر مقدمة واساس في تخصص الطاقة الكهربائية وتوليدها ونقلها وهو مشابه لكورس EE 306 في قسم الهندسة الميكانيكية ومن متطلباته EE 213 لطلاب الكهرباء و EE 204 لطلاب الميكانيكية.\n\nهذا الكورس راح يغطي كل من هذه المواضيع:\n١- Three Phase Circuits\n٢- Introduction to Machinery Principles, magnetic Circuits\n٣- Transformers\n٤- DC Machines, motors and generators\n٥- Synchronous Machines\n٦- Three-Phase Induction Motor\n٧- Transmission Line\nتقييمي للكورس:\nالكورس بشكل عام متوسط ما هو صعب ولا سهل ويمتاز بطول المنهج وكثرة المعادلات فيه ويحتاج للحفظ بعض مرات وعدا عن ذلك يوجد فيه تكرار من سيركت ١ وسيركت ٢ بحيث تحتاج بعض مرات قوانين منهم لتحليل الدوائر مثل KVL و KCL. وبعد اعتبر هذا الكورس مهم للطلاب اللي يبون يتخصصون بمجال الطاقة بمواد المستوى الرابع. انصحك بهذا الكورس بالكتاب وحل الامثلة اللي فيه واقصد بالكتاب حق Chapman واذا امداك تفتح كتاب Sen وتطلع على اللي فيه يكون افضل.\n\nبالرابط بالاسفل تلقى ملفات تساعدك باذن الله على هذا الكورس:\n- هنا -", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/119808/97", "user": "AHMED_SH", "ts": 1445104409000, "tid": 119808, "pn": 97}}', 1445104409000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1160026-ee360', 'stk-sstem', 'EE 360', 'srcP', '{"html": "تفضل طل عمرك هذي اخر هوموركين 🙂<br><br>​<span data-fid=\"stk-f1160026-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1160026-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1160026-0": {"name": "360-HW6.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/33702f7af2d4a894d8c9557608ec841f39241ae1fa32c172e3a948ec4887bd26"}, "stk-f1160026-1": {"name": "360-HW7.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee360/138003/2", "user": "sstem", "ts": 1357678209000, "tid": 138003, "pn": 2}}', 1357678209000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1160038-ee360', 'stk-user6202', 'EE 360', 'srcP', '{"html": "تفضل<br><br>​<span data-fid=\"stk-f1160038-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1160038-0": {"name": "HW EE360.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/24c727ff9cf0be4e0daf55e31ad8c280a4b0fdec2da4d87d449eda8a5148b3dd"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee360/138003/5", "user": "user6202", "ts": 1357678808000, "tid": 138003, "pn": 5}}', 1357678808000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1160411-ee360', 'stk-mathematician', 'EE 360', 'srcP', '{"html": "دعواتك<br><br>​<span data-fid=\"stk-f1160411-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1160411-0": {"name": "FINAL-EE360-071-sol.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/db276336ffd2cbfe7dfcd7d34bfcfd8b433bcf5f211863406515f93900e1c71d"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/138041/2", "user": "MATHEMATICIAN", "ts": 1357720420000, "tid": 138041, "pn": 2}}', 1357720420000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-magbool-ee360', 'stk-magbool', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f98502", "n": "Dr. Ibrahim Habiballah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 360 -152\n\nبنود التقييم :\n\nالتحضير :\nOn time في بداية الكلاس ، وإذا تاخرت شويه يحطك ليت.\n\nطريقة الشرح :\nشرحه سلس وواضح ، ونوته ممتاز ومليان أكثلة ويغني عن الكتاب، لكن فيه مشكلة وحدة إنه شرحة كله ع نفس ل tone ، وكان كلاسي أبو ساعة وربع، فبعد فترة تمل ويجيك النوم.\n\nالكويزات :\nسهلة جدا ، يجيبها زي الاولد كويزز الموجدة بموقعه ، من سؤالين ل أربعة ، اختيارية ، ويجيبكم الظهر يوم الثلوث الساعة 12:20 عشان تختبر، الكوية ماياخد 5 دقايق.\n\nالمياجر:\nسهلة الصراحة ، لكن تصحيحه شدييييد.\n\nالفاينلات :\nزي المياجر.\n\nالقريد النهائي: A\n\nالصوت:\nواضح.\n\nإضافات :\nفي البداية كنت متردد أنزل معاه بسبب الكلام اللي قريته هنا، لكن تفاجأت إنو الدكتور غير ، أخلاقه حلوة ويعرف الطلاب وتعامله معاهم ممتاز، أحيانا يجي قافل للكلاس ويكون شديد لكن هذا الشي نادر جدا، يعطي كلاسات أوف كثير 😃 ، دايما يحذر الطلاب من الأخطاء اللي تتكرر في الميجر عشان لا يطيحوا فيها .\n\nالله يوفقه دكتور ممتاز.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1451075-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-habiballah/98502/16", "user": "magbool", "ts": 1464991193000, "tid": 98502, "pn": 16}}]}', 1464991193000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6130-ee360', 'stk-user6130', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f98513", "n": "Dr. Belhaj Chokri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله ،،،\nee 360 سمستر 111 ،،،\n\nالشرح : باختصار إذا تبي تفهم البور نزل عند ذا الدكتور شريح لأبعد حد و يكتب نوت و يحل أمثلة و يوضح لك أفكارها بشكل رهيب.\n\nالتحضير : يحضر كل يوم ينادي الأسماء و لا مرة نسى.\n\nالكوزات : سهلة جداً يجيبها من النوت و الهوموركات و طريقته يعطيك هومورك كل و يك إند و تسلمه السبت و يوم الأثنين كويز على ماتريال الكويز و أشوف هذي الطريقة رائعة تخليك تذاكر الكورس غصب.\n\nالمياجر : سهلة بس طويلة بس مع البراكتس و معرفة استخدام الحاسبة في حسابات الكومبلكس نبر راح يمديك إن شاء الله.\n\nالفاينلات : كومن و سهلة نفس مستوى المياجر.\n\nإضافات :\n* في نقطة مهمة في ذا الكورس و هو معرفة استخدام الحاسبة في حسابات الكومبلكس نمبر لأنها راح توفر عليك وقت في حل المسائل.\n* إذا نزلت مع الدكتور شكري لا تهمل لأن ما راح يرحمك في الكلاس ورك.\n* بالنسبة لتصحيح الدكتور أشوفه شين صراحة و هذا عيبه الوحيد.\n\nالقريد النهائي : A+ .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970925-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/belhaj-chokri/98513/4", "user": "user6130", "ts": 1326986222000, "tid": 98513, "pn": 4}}]}', 1326986222000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2781-ee360', 'stk-user2781', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f98513", "n": "Dr. Belhaj Chokri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ee 360 - من زماان\n\nالتحضير : ما اذكر\nطريقة الشرح : شرحه ممتاز الدكتور بس الي يعيبه انه ما يشرح إلا باخر عشر دقايق وياخذ خمس دقايق زيادة عن وقت الكلاس، وباقي الوقت يكتب نوت !. بصراحه متندم اني خذيت عنده الـ 360، يوم طلعت في الليفل فور اكتشفت اني مخدوع بالدكتور. كان يشرح لها ثيوري سريع سريع ويعلمنا كيف نحل وانتهت السالفه …\n\nالكويزات : كويزاته كانت سهله نوعاً ما\nالمياجر: ميجر ون وتو كانوا سهلين\nالفاينلات : الفاينل صعبه شوي\nالقريد النهائي: القريد عند الدكتور سيئ مع احترامي له. قبل الفاينل لو الافريج c كان المفروض ع درجاتي b+ او a والفاينل حال تمااااااام والناس تقول صعب وبالاخير c+ 😦\nحتى الفيرست اونر ما ياخذ عنده قريد …\n\nالبروجيكت: كان عبارة عن ديزاين بربلم وكانت سهله وجاب شي يشبهها بالفاينل …\n\nالصوت: ممتاز وواضح\n\nإضافات : بصراحه ما انصح فيه، شرحه تمام بس ما راح تستفيد من الكورس معه إذا انت اهتمامك بور", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1053737-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/belhaj-chokri/98513/7", "user": "user2781", "ts": 1339351506000, "tid": 98513, "pn": 7}}]}', 1339351506000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hammmod-ee360', 'stk-hammmod', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f98513", "n": "Dr. Belhaj Chokri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم : EE360 Term 161\n\nالتحضير : يوميا نهاية الكلاس أو في النص.\nطريقة الشرح : The most classical way; يجي ويعبي السبورة واكتب وراي. طبعا بداية التشابتر يمكن يقعد كلاس كامل يشرح لك الكونسبت الأساسي (يستخدم البروجكتر كثير سواء يوريك صور أو يعرض فيديوات) ويجاوب على جميع تساؤلات الطلاب ويرحب بالأسئلة والنقاشات، هذا أطلق جزء في شرحه. طبعا ينقل الأمثله من نوته في يده ويحرص على تفاعل الطلاب أثناء الحل، ويستخدم ألوان عشان يوضح لك (بس خطه مخيس شوي 😅)\nالكويزات : كثيرة ومعظمها متوسطة إلى سهلة، لأن الكورس كذا. ولو تدور أولد كويزز له بتلقاه يكررها.\nالمياجر: بعد سهلة الى متوسطة وكلها مسائل بدون كونسبتشوال.\nالفاينلات : مبعد اختبرنا\nالقريد النهائي:A\nالصوت: واضح وعالي وآكسنت بريطاني فخم\nإضافات : أول الترم كنت مفتون فيه مرة بعدين عادي تلاشت الغمة وصرت أشوفه ممل شوي (يمكن لأنه آخر كلاس في اليوم والمادة يصير فيها تكرار أصلا). كان عنده مشكلة ياخذ زيادة عالوقت، طبعا هو لمصلحتنا لأنه يسهب في الشرح وإجابة تساؤلات الطلاب.\n\nلو يرفع نوتاته عالبلاك بورد وما يحتاج تكتب معه بيكون بالنسبة لي مثالي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1465057-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/belhaj-chokri/98513/19", "user": "hAmMmOd", "ts": 1482413872000, "tid": 98513, "pn": 19}}]}', 1482413872000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo-da7m-ee360', 'stk-abo-da7m', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f98513", "n": "Dr. Belhaj Chokri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه EE360 الفصل 161\n\nالتحضير :\nينادي الأسماء واحد واحد بنص المحاضرة.\n\nطريقة الشرح :\nينقل من نوته - اللي يكون ملخصه من مراجع كثرة - ويكتبه على السبورة بخط يده وبألوان متعددة. بعد ما يكتب يشرح كل شيء كتبه ويستعين بالبروجكتر لو كان فيه فيديو أو صور توضح أكثر.\n\nيعطي أمثلة ويحلهم شوي شوي ويخلي كل الطلاب مهما كان مستواهم يشاركون بالحل ويدخلون بجو الكلاس، وهذا أكثر ما يميز الدكتور.\n\nالكويزات :\nيعطي من5 إلى 6 كويزات شبيهات بالهوم وورك وطوال شوي.\n\nالمياجر:\nكومن، الفصل 161 كانت سهلة بشكل مدهش مقارنة بباقي الفصول.\n\nالفاينلات :\n4 أسئلة، الأول خيارات على متيريال المياجر\n\nو ال3 الباقيات طوال وفيهم حل وتفصيل ويكونون على ماتيريال ما بعد الميجر الثاني.\n\nالقريد النهائي:\nA + بلا مناع كتقييم للدكتور.\n\nما أعرف عن توزيعه للقريدات النهائية، أخذت القريد اللي توقعته من دون ما أشوف درجتي بالفاينل.\n\nالصوت:\nواضح، آكسنت بريطاني فخممم جدا. ومتمكن مرة باللغة ويسخدم كلمات ومجاز يوصل لك اللي بيقوله ببراعة.\n\nإضافات :\n* أفضل دكتور كهرب مر علي.\n* فاااهم جدا ويفصل المسائل ويعلمك شلون تكون مهندس بتفكيرك بحل المسائل.\n* أثر بي كثير بطريقة شرحه وتفكيري تجاه المسائل الهندسية صار مختلف بعد ما أخذت الكورس معه.\n* مهما كان مستواك بيشجعك تتفاعل وتشارك.\n* مهم جدا جدا تسجل معه أول بأول - لإنه ما ينزل نوته على البلاكبورد- ، راح توفر على نفسك كثيير تعب لإن الاختبارات والكويزات نفس اللي يجيبه ويكتبه بالكلاس. الكتاب يشتت ولا يشرح زين.\n* فيه سلبية أنه بياخذ كثير من وقت البريك ولا يطلعك لو كان بعد كلاسه بريك ما ينهي المحاضرة بوقته.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467334-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/belhaj-chokri/98513/20", "user": "abo-da7m", "ts": 1485809001000, "tid": 98513, "pn": 20}}]}', 1485809001000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-ee360', 'stk-mr.a1', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f172585", "n": "Dr. Mohammed Shoaib Shahriar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 171 EE 360 (Lab)\n\nالتحضير :\nبداية كل لاب ياخذ التحضير ، نفس نظام القسم من ناحية التأخير والغيابات …الخ.\n\nطريقة الشرح :\nيكتب الأشياء اللي يحتاجها والبروسيجر باختصار على السبورة ، ويبدأ يتكلم عن التجربة والخطوات اللي نتبعها في شغلنا. مستوى الشرح بالنسبة لي ممتاز وواضح. إذا كان فيه شيء جديد بنستخدمه يشرح لنا كيف نتعامل معه.\n\nالكويزات :\nكويزين ريتن ، كلها كونسبت. مستواها عادي ، فيها أسئلة سهلة وفيه أسئلة تحتاج تفكر فيها وتكون فاهم وش قاعد تسوي في اللاب.\n\nالمياجر:\nاختبارين عمليين. يعطيك السيركت ويطلب منك تشبكها وتسوي شغلة على برنامج Cassy Lab، وهو يجي يشيك على شغلك إذا صح أو لا.\nنصيحة: لا تضيّع درجات هالاختبارين ، تراها سهلة جدا وما فيها شغل.\n\nالفاينلات :\nريتن ، كان مستواه عادي بس فيها أسئلة غريبة اشوي ، بالإضافة\nلبعض المسائل الخفيفة اللي جابها.\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح وجيد ، أكسنت جنوب آسيوي (هندي ، باكستاني ، …الخ) ، في البداية بيتعبك بس بتتعود عليه.\n\nإضافات :\n١. حاول تكتب النقاط اللي يتكلم عنها الاستاذ في اللاب (ليش استخدمنا الجهاز/القطعة الفلانية ، وش الهدف من التوصيل بطريقة كذا ، ليش صار كذا بعد ما سوينا شغلة معينة …الخ) ؛ لأن هذه النقاط هي اللي راح تجيك في الكويزات والفاينل.\n٢. أحد النقاط السلبية على الاستاذ هي ريبورتاته ، طويلة وفيها أشياء ما لها سنع ، مثل أنه يطلب منك تكتب theory بسيط أو procedure للتجربة ، ما لها حاجة. فايدتها الوحيدة بتخليك تشغّل كورسات الانجلش اللي درستها 😆.\n٣. الاستاذ مرتب درجة أولى. يرفع كل الدرجات على البلاك بورد بشكل أسبوعي ، وحتى مواعيد الكويزات والاختبارات العملية يحددها لك في السيلبس من بداية الترم ، يعني من ناحية التنظيم ١٠/١٠.\n\nبالنسبة لي أشوفه أستاذ ممتاز وحبيب ومحترم في تعامله مع الطلاب ، وما شفت عليه شيء مو كويس غير اللي ذكرته هنا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485090-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohammed-shoaib-shahriar/172585/3", "user": "Mr.A1", "ts": 1514325725000, "tid": 172585, "pn": 3}}, {"id": "stk-dr-f98513", "n": "Dr. Belhaj Chokri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 171 EE 360\n\nالتحضير :\nبداية أو نص المحاضرة ، ينادي بالأسماء. أعتقد يعطي ليت ، وإذا تأخرت مرة ممكن يطردك وما يخليك تدخل الكلاس.\n\nطريقة الشرح :\nنوت على السبورة ، ويشرح الكونسبت بشكل شفهي ويعلق على الأشياء اللي يكتبها. يستخدم بعض الفيديوهات التعليمية أحيانا لما يدخل لتشابتر جديد ، بحيث يعطيك فكرة عن اللي جايك بطريقة جميلة. في المجمل ، شرح الدكتور ممتاز ومتمكن من المادة بشكل كبير ، أقدر أقول ما كذب اللي سماه ملك الباور.\n\nالكويزات :\nأخذنا ٥ كويزات ريتن خلال الترم ، قال بيحتسب أفضل ٤. مستوى الكويزات بشكل عام سهل ، يجيبها من كويزات قديمة ، من الهومورك ، أو حتى مثال هو شرحه في النوت ممكن يجيبه في الكويز.\n\nالمياجر:\nكتب الميجر الأول كامل ، وكان سهل وفيه أسئلة نسخ لصق من مياجر قديمة هو كاتبها 😆. الميجر الثاني كتبه الدكتور الثاني ولقينا فيه أشياء جديدة عن الاولد اقزام.\n\nالفاينلات :\nكومون بين الدكتورين ، كان مستواه عادي. يعيبه إنه كان طويل اشوي -وممكن هالنظام يتغير حسب الدكاترة- ، كان ١٥ فقرة اختيارات أغلبها كونسبت ، بالإضافة إلى ٤ مسائل ريتن طويلة نسبيا.\n\nالقريد النهائي:\n+A\n\nالصوت:\nجيد جدا ، وواضح للكل.\n\nإضافات :\n١. تصحيحه للكويزات والمياجر سفاح اشوي. إذا جبت النواتج النهائية صحيحة بتاخذ درجة كاملة ، غير كذا احتمال يقص نص درجة السؤال عليك.\n٢. أعطانا بروجيكت حلو وخفيف ، تصميم محطة صناعية مكونة من محول و ٤ محركات ، والمطلوب منك تصممها لتحقق متطلبات محددة بالإضافة لتصميم الكوابل اللي توصل المحول بالمحركات. يعني بروجيكت هندسي وفيه تطبيق جيد للمفاهيم اللي تعلمتها في المادة.\n٣. للأسف للحين ما نزل درجات الكلاس وورك ولا البروجيكت ، وأعتقد إننا بناخذ الفاينل قريد واحنا مو عارفين درجاتنا.\n٤. تعامل الدكتور رسمي مع الطلاب ، لكنه ما يخلو من بعض المزحات الخفيفة وسط الشرح (يلطّف جو الكلاس اشوي).\n\nاستفدت كثير من د. شكري من الناحية العلمية والهندسية ، وأشوف إني أخذت مقدمة ممتازة في الباور معه. الله يعطيه العافية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485691-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/belhaj-chokri/98513/21", "user": "Mr.A1", "ts": 1515362271000, "tid": 98513, "pn": 21}}]}', 1514325725000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10387-ee360', 'stk-user10387', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f98513", "n": "Dr. Belhaj Chokri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور درست عنده EE360, E466, EE465 وتعامله في اختلاف طفيف في اختلاف الكورس\n\nالتحضير :\nفي كورسات لفل 4 يكون ما يركز عالتأخير كثير ، ويحضر إما وسط الكلاس أو نهايته ، ونادرا ما يعلق على تأخير أي طالب بحجة إنك خلاص صرت كبير وأفهم بمصلحتك.\n\nفي لفل 3 ونازل يحضر مع بداية الكلاس ويسجل تأخير.\n\nطريقة الشرح :\nيكتب على السبورة بشكل مرتب وللأسف زي ما قال عبد الرحمن يركز عالرياضيات كثير والاشتقاق ، ولكن عنده علم كثير لو استطردت وسألته عن موضوع له دخل في الpower في الكلاس وربطته باللي كان يقوله من قريب أو من بعيد راح يشرح لك أشياء عملية رهيبة وبدون أي ضجر. وأهم شي تكتب معاه للفائدة القصوى ، طبعًا كتبت نوتة معاه لكل كورس كنت فيه معاه\nEE 360 تلقونها في الليقاسي حق التخصص.\n\nEE 466 and EE 465 تلقونها في الريسورس حق الجامعة.\n\nالكويزات :\nالكويزات تحتاج شوية تركيز ، ولكن في طريقة أخرى وهي إنّك تبحث عن اختبارات مياجر أو فاينلات قديمة هو كاتبها ، بتشوف إنها تجي نسخ ولصق من أسئلة المياجر وإذا مرة مرة غير بعض الارقام. طبعا يكون سؤال واحد ويعطيك ثلث ساعة الى نصف ساعة للكويز.\n\nالمياجر:\nتكون مطابقة للمياجر القديمة أو مع تغيير طفيف في الأرقام ، فإذا لقيت مصادر لمياجر هو كاتبها من قبل ، أنصحك تتخذها مصدر أساسي للمذاكرة.\n\nالفاينلات :\nهنا تبدأ لعبته ، يسلخ الطالب سلخ في الفاينل ، يتفنن ويلعب بالأسئلة بطريقة يحاول ينزل فيها الأفرج بطريقة أو بأخرى ، لاحظت عليه إن في الاختبار النهائي يصحح من الجواب النهائي ، اذا كان غلط تنقصك ٣ أرباع الدرجة وإذا كان طريقتك صح ممكن يعطيك الربع الأخير.\n\nالدكتور باختصار جزّار في التصحيح.\n\nالقريد النهائي:\nC+\n\nالصوت:\nصوت واضح جدا ومسموع.\n\nإضافات :\nالدكتور غدراته كثيرة دائما وأبدا. وكل كورس درسته عنده غدر في طلابه.\nEE360: سؤال في الفاينل كان عليه ١٠ او ٥ اذا ما خاب ظني ، ووقت التصحيح غير رأيه ودبّل الدرجة اللي كانت عليه ونقص من ثقل باقي الأسئلة.\n\nEE466: الطلاب طلبوا تأجيل تسليم المشروع ووافق لهم وقال لهم تقدروا تسلموه بعد الفاينل ب 3 او 4 ايام .\nولكن المفاجأة إن جاب سؤال في الفاينل عليه ٢٥/١٠٠ في الاختبار النهائي ، أنا ولله الحمد ما تضررت من هالشي ولكن أعلمك كيف إن مستحيل تسلم من غدره ، طبعا بعض الأسئلة غلطت في فاصلة ببداية السؤال وشطب علي السؤال كامل وعطاني ٥/٢٥ فيه ، بحجة إن أنت مهندس ما تغلط في الرياضيات.\n\nEE465: كان توزيع الدرجات كالتالي\n20% لميجر ١\n20% لميجر ٢\n30% للفاينل\n\nولما جينا نختبر الفاينل اكتشفنا ان التوزيع اختلف وصار كالتالي:\n15% لميجر ١\n20% لميجر ٢\n35% للفاينل\n\nطبعا لولا سؤال أحد الطلاب عن التوزيع ما درينا أن هذا التغيير صار. لما استفسرت منه قال وبكل برود: أنا قلت من بداية السمستر أحتفظ بالحق على التعديل توزيع الدرجات بما تقتضيه المصلحة العامة. طبعا أنا أشوفه كلام عارٍ من الصحة جملةً وتفصيلًا. قام بتغيير التوزيع بما يكفل إن يصير التوزيع أفرج هابط بأي طريقة.\n\nطبعاً إذا مسك كورس دائمًا يخلي الأفرج C+.\n\nوالسلام خير ختام", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509213-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/belhaj-chokri/98513/25", "user": "user10387", "ts": 1556642469000, "tid": 98513, "pn": 25}}]}', 1556642469000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_only-ee360', 'stk-_only', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f98514", "n": "Dr. M Shwehdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أتفق تماما مع الأخ d7ooomy إلا في نقطة المياجر، أنا أخذت عنده EE360 في فصل 093 … ميجر ون كان سؤالين واحد سهل و واحد صعب أما ميجر تو كان متوسط الصعوبة و الفاينل كان مررررررة سهل … تصحيحه سيء جداً جداً … أنصح به للذي يريد أن يفهم الحياة العملية أكثر من القريد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p898814-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-shwehdi/98514/6", "user": "_ONLY", "ts": 1315720606000, "tid": 98514, "pn": 6}}]}', 1315720606000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8180-ee360', 'stk-user8180', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f98533", "n": "Dr. M Abdur-Rahim", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 360 semester 102\nالتحضير : بشكل يومي (( يمرر روقه على الطلاب))\nطريقة الشرح : ملخبط شوي مره يشرح على السبورة ومره يشرح على السلايدات وشرحه يجيب النووووم (( كنت اجي للمحاضره شبعان نوووم وشارب نسكافيه وبالرغم من ذلك انام بالمحاضره)) ومحاضرته ممله الى ابعد الحدود لكن لازم تنتبه معه لأنه مرات يقط قطات تجي بالمياجر والفاينال\nالكويزات : سهلة جداً وتأتي من الهوموركات (( الهوموركات من برى الكتاب))\nالمياجر: سهله\nالفاينلات : سهله\nالقريد النهائي: أعطيه A\nالصوت: متوسط\nإضافات : الدكتور هذا انا ما فهمت له مره تجيه بالأوفس يرحب فيك ويجاوب على أسئلتك بكل صدر رحب ومره تجيه للأوفس يقعد يشرشح فيك ويحطمك ويقول انت ماتفهم ومن هذا القبيل لكن الدكتور طيب مع الطلاب أكثر من اللزوم ومن كثر طيبته الطلاب فلوها بالكلاس تجي تدخل الكلاس ما تلقى احد قدام كلهم ورى وسوالف ((شغل ثانوي)) وعصب علينا وقام يدقق بالتحضير لدرجة انه بغى يعطي واحد من الشباب دي ان وقام يهددنا بالفاينال انه يبي يجي صعب ولكن بالنهاية جاب لنا اسهل فاينال من دخلت الجامعه (( copy paste from the homeworks problem )) وتصحيحه دلع ويدف الطلاب قريدات أنصح فيه للطالب اللي يبي قريد ولكن ما أنصح فيه للي يبي يفهم (( الكتاب حلو وسهل لكن يأخذ منك وقت اكثر مما تستحق المادة لأنها سهله جداً فأنصح للي يبون يفهمون المادة ولا يتعبون فيها ينزلون مع بالحاج لكن تصحيحه شين))", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p893258-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-abdur-rahim/98533/13", "user": "user8180", "ts": 1314618013000, "tid": 98533, "pn": 13}}]}', 1314618013000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-eng_mohamed-ee360', 'stk-eng_mohamed', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f98533", "n": "Dr. M Abdur-Rahim", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ee360 - 121\nالتحضير: ورقة تمر في بداية الكلاس\n\nالشرح: من وجهة نظري جيد … انتبه معاه وهتفهم منه … أحلى حاجة فيه هو حله لمجموعة من المسائل مع نهاية كل جزئية … سلايداته جيدة … ويشجع الطلاب على المشاركة في حل المسائل والإجابة على مختلف الأسئلة … الحمد لله اعتمدت على الله ثم على شرحه والسلايدات … وكان أسهل كورس عدى عليّ\n\nالكويزات: سهلة … مثل المسائل اللي يحلها ف الكلاس أو الهوموورك\n\nالمياجر: كومون\n\nالفاينل: كومون\n\nالجريد النهائي له: A\n\nالدكتور شرحه مناسب للكورس ويفهم (من وجهة نظري) ، بالإضافة إلى أخلاقه العالية وتعامله الطيب مع الطلاب خاصة المتفوقين … بالإضافة إلى انه يساعد ف التصحيح ويقدر الطالب الفاهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1164493-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-abdur-rahim/98533/18", "user": "Eng_Mohamed", "ts": 1358239143000, "tid": 98533, "pn": 18}}]}', 1358239143000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-non-zero-ee360', 'stk-non-zero', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f115351", "n": "Dr. Ali T. Al-Awami", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت عنده ee360 …\n\nشريح جدا جدا جدا افضل دكتور مر علي بالجامعه ( بالنسبه لي بعض الشباب ما عجبهم شرحه )\n\nصوته ممتاز جدا …\n\nيحضر يوميا والحضور عنده عليه درجه وحده تقريبا ثلاث ارباع السكشن اخذ الدرجه …\n\nيحب الطلاب يسالونه ويجاوب اجوبه سهله تخليك تفهم غصب عنك لو تبي تفهم …\n\nباختصار بدون ما اطول الموضوع اعطيه a+ …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1044989-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ali-t-al-awami/115351/8", "user": "Non-ZeRo", "ts": 1338030034000, "tid": 115351, "pn": 8}}]}', 1338030034000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedgs-ee360', 'stk-mohammedgs', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f115351", "n": "Dr. Ali T. Al-Awami", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE360-T201 (Online)\n\nالتحضير: ما يحضر بشكل مباشر بس ياخذ تقرير الحضور من التيمز، لما نزلت درجات الحضور تفاجأ بعض الزملاء إنه خاصم عليهم على الغياب مع إنه ما نبهم.\nطريقة الشرح: يشرح عن طريق منصة تيمز من السلايدات، شرحه ممتاز بس يعيبه إنه ما يحل مسائل واجد، أحيانًا يحل بورقة وقلم ويشغل كاميرا الجوال عشان نشوفها بس مرات قليلة.\nالكويزات: متوسطة أغلب الوقت تجي من أفكار الهومووركات وأحيانًا يجيب أفكار جديدة وفيه كم كويز كان أغلبها كونسبت. طبعًا الكويزات كلها على البلاكبورد خيارات وفراغ ويكون بداية الكلاس.\nالمياجر: كومون على البلاكبورد.\nالفاينلات: كومون على البلاكبورد.\nالقريد النهائي: B+\nالصوت: واضح وأغلب الوقت يتكلم انجليزي بلهجة ولغة واضحين.\nإضافات:\n١- الدكتور يرد على التيمز فلو عندك سؤال لا تتردد تسأله.\n٢- الدكتور يشجع الطلاب يجونه في الاوفس لو في حاجة ما فهموها ودايم يكون في الاوفس اورز حقته تقدر تدق عليه تيمز وتكلمه.\n٣- الدكتور حبيب وأخلاقه حلوة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527539-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ali-t-al-awami/115351/20", "user": "MohammedGS", "ts": 1609718758000, "tid": 115351, "pn": 20}}]}', 1609718758000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ee360', 'stk-guest', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f115351", "n": "Dr. Ali T. Al-Awami", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE360 - term 201\nالتحضير : مايحضر في الكلاس ولكن ياخذ التقارير من التيمز\nالشرح : شرحه ممتاز جدا ولكن كنت اتمنى يحل المسائل عن طريق الكتابه في البوربوينت او باستخدام جهاز معين\nالكويزات : على البلاكبورد ولازم تكون ملم في المواضيع لان احيانا يجيب اسئله كونسبت\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي : B\nاضافات : الدكتور متفاعل مع الطلاب ودائما موجود في التيمز للرد على اسئلة الطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527600-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ali-t-al-awami/115351/21", "user": "Guest", "ts": 1609833550000, "tid": 115351, "pn": 21}}]}', 1609833550000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7502-ee360', 'stk-user7502', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f152985", "n": "Dr. Mohammad Al-Muhaini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 360 …Semester 131\n\nالتحضير :\nشديد و طبعا في أول الكلاس\n\nطريقة الشرح :\nنوعا ما مملة , يشرح من سلايدات , كتابته في السبورة قليلة … لكن ما أظلمه السلايدات و الاوفيس أور كافيات .\n\nالكويزات :\nمتوسطة إلى سهلة\n\nالمياجر:\nمتوسظة إلى سهلة\n\nالفاينلات :\nمتوسطة\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح\n\nإضافات :\nالدكتور حبيب و أخلاقه عالية و متساعد في الأوفس أور فمن الطبيعي أن أنصح به …\nبس فيه حاجة ما حبيتها اللي هي : طبعا أغلب الطلاب يجون تعبانين و يشعرون بالإرهاق ف يرقدون ( طبعا و هم جالسين مهو يحطون روسهم على الطاولة 🤠 ) وبعضهم يحسون بالملل من شرحه ( مثلي 🤠 ) فالدكتور إذا لاحظ أحد مغمض عيونه يخصم عليه درجة من المشاركة سيدة و بدون تفاهم ههههه .\n\nو السلام", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1353539-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-muhaini/152985/3", "user": "user7502", "ts": 1397758252000, "tid": 152985, "pn": 3}}]}', 1397758252000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muath.12-ee360', 'stk-muath.12', 'EE 360', 'doc', '{"docs": [{"id": "stk-dr-f152985", "n": "Dr. Mohammad Al-Muhaini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه EE360 الفصل 202 أون لاين\n\nالتحضير :\nدائمًا بداية الكلاس ينادي على الأسامي على جولتين إذا فاتتك الجولة الأول انتظر الجولة الثانية اذا ما رديت فيهم غالبًا راح يعطيك تأخير.\n\nطريقة الشرح :\nالدكتور شريح بما تعنيه الكلمة، يمشي على السلايدات ويشرح المفاهيم وبعدها يحل أمثلة بعد كل مفهوم وصدقني إذا مركز معه المذاكرة ما راح تاخذ منك وقت طويل\n\nالكويزات :\nالكويزات تكون بداية كل أسبوع زوجي يعني لا تتوقع منه يقول لك أنه في كويز، كان ينزعج حتى من الطلاب اللي يسألون عن هذا الشي. كويزاته غالبًا كانت متوسطة الصعوبة.\n\nالمياجر:\nحولوها لميد وكان مقسم لثلاث أجزاء، أول جزء كله خيارات ويكون كله اسئلة كونسبت غالبًا يكون سهل إذا كنت فاهم، البارت الثاني والثلاث كانت نفس بعض وكانت نوعًا ما صعبة بس اللي خلّ الأفرج معقول هو الدرجة العالية اللي حاطينها للبارت الأول.\n\nالفاينلات :\nنفس الميد لكن الدرجات لأغلب الطلاب كانت صدمة، لكن الدكتور طمنهم أن في رينج للإجابات راح يتعدل وفعلًا ارتفعت درجات الطلاب كثير.\n\nالقريد النهائي:\nC+ بسبب تعامله\n\nالصوت:\nواضح.\n\nإضافات:\nالدكتور للأمانة شرحًا لا يعلى عليه لكن من ناحية تعامل للأسف كان وقح مع أغلب الطلاب خاصة بالردود تحس أنه يحاول يضحك الطلاب عليك، غير أنه على ما يبدو في واحد بالسكشن الثاني سوى حركة بايخة والدكتور شملنا مع السكشن الثاني بالعقوبة كان عادي يوقف شرح من نص الكلاس وينادي واحد من الطلاب بالإسم ويسأله عن شيء شرحه خلال الكلاس أو الكلاس الماضي وإذا ما عرف يجاوب يطرده من الكلاس ويحسبه غياب حتى لو كان حاضر 49 دقيقة من المحاضرة طبعًا بذي الحركة ينطرد كل كلاس على الأقل 4 أو 5 طلاب طبعًا بغير وجه حق بحجة أنك ما عرفت تجاوب معناها أنك نايم ولا مو حول الجهاز ما عنده ما فهمت نقطة أو ما راجعتها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531204-ee360", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-muhaini/152985/8", "user": "Muath.12", "ts": 1628777296000, "tid": 152985, "pn": 8}}]}', 1628777296000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
